HTML = '''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>magicStudio Modern</title><style>
:root{--bg:#070a12;--panel:#111827;--panel2:#172139;--line:#2d3b58;--text:#f4f7ff;--muted:#97a8c6;--accent:#7c5cff;--good:#42d392;--warn:#ffd166;--bad:#ff6b6b}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#070a12,#0c1324 55%,#060913);color:var(--text);font-family:Segoe UI,Malgun Gothic,Apple SD Gothic Neo,sans-serif}.app{max-width:1320px;margin:0 auto;padding:22px 18px 96px}.top{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}.brand{font-size:28px;font-weight:900;letter-spacing:.2px}.topRight{display:flex;gap:8px;align-items:center}.pill{background:#151f35;border:1px solid var(--line);border-radius:999px;padding:8px 12px;color:#cfdbf7;font-size:13px}button{border:0;border-radius:14px;background:#25334f;color:#eef3ff;font-weight:850;padding:12px 14px;cursor:pointer}.primary{background:linear-gradient(135deg,#6c54ff,#9b78ff)}.good{background:linear-gradient(135deg,#2fd084,#80eab5);color:#06160d}.warn{background:linear-gradient(135deg,#ffbf59,#ffe08a);color:#1d1500}.ghost{background:#172139;border:1px solid var(--line)}.hero{display:grid;grid-template-columns:1fr 380px;gap:16px}.card{background:rgba(17,24,39,.96);border:1px solid var(--line);border-radius:24px;overflow:hidden;box-shadow:0 24px 80px #0008}.head{padding:15px 18px;background:rgba(23,33,57,.92);border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;font-weight:900}.body{padding:18px}.titleInput{display:grid;grid-template-columns:240px 1fr;gap:10px;margin-bottom:12px}input,textarea,select{width:100%;background:#080f1f;color:var(--text);border:1px solid #34445f;border-radius:15px;padding:12px;outline:none}textarea{line-height:1.58;resize:vertical}.masterPrompt{min-height:132px;font-size:20px;border-radius:22px;padding:18px}.tabs{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin:16px 0}.tab{background:#10192d;border:1px solid var(--line);border-radius:16px;padding:13px;text-align:left}.tab.active{background:#2a2460;border-color:#8f7dff}.tab b{display:block}.tab span{display:block;color:var(--muted);font-size:12px;margin-top:4px}.workspace{display:grid;grid-template-columns:310px 1fr 360px;gap:16px}.stagePanel{display:none}.stagePanel.active{display:block}.project{background:#0b1324;border:1px solid var(--line);border-radius:15px;padding:12px;margin-bottom:9px;cursor:pointer}.project.active{border-color:#8f7dff;background:#182342}.project b{display:block;margin-bottom:4px}.small{font-size:12px;color:var(--muted);line-height:1.5}.promptBox{min-height:92px}.script{min-height:340px}.actions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px}.steps{display:grid;gap:9px}.step{display:flex;align-items:center;justify-content:space-between;background:#0b1324;border:1px solid var(--line);border-radius:15px;padding:12px}.dot{width:12px;height:12px;border-radius:50%;background:var(--warn)}.dot.ok{background:var(--good)}.dot.bad{background:var(--bad)}video{width:100%;border-radius:18px;border:1px solid var(--line);background:#000}.log{height:240px;white-space:pre-wrap;overflow:auto;background:#060b16;border:1px solid var(--line);border-radius:16px;padding:13px;color:#dce6ff}.bar{position:fixed;left:50%;bottom:16px;transform:translateX(-50%);width:min(1040px,calc(100vw - 30px));display:grid;grid-template-columns:1fr 140px;gap:10px;background:#111827;border:1px solid var(--line);border-radius:22px;padding:12px;box-shadow:0 22px 70px #000a}.settings{display:none;position:fixed;right:22px;top:76px;width:380px;background:#111827;border:1px solid var(--line);border-radius:24px;padding:18px;box-shadow:0 24px 90px #000b;z-index:10}.settings.show{display:block}.sceneCard{background:#0b1324;border:1px solid var(--line);border-radius:15px;padding:12px;margin-bottom:10px}.sceneCard b{display:block;margin-bottom:5px}@media(max-width:1120px){.hero,.workspace,.titleInput{grid-template-columns:1fr}.tabs{grid-template-columns:1fr 1fr}.bar{grid-template-columns:1fr}}
</style></head><body><div class="app"><div class="top"><div class="brand">magicStudio</div><div class="topRight"><span class="pill" id="projectState">프로젝트 선택</span><span class="pill" id="assetState">자산 대기</span><button class="ghost" onclick="toggleSettings()">설정</button></div></div><section class="hero"><div class="card"><div class="head"><span>AI 제작 지시</span><button class="good" onclick="makeAll()">전체 자동 제작</button></div><div class="body"><div class="titleInput"><input id="title" value="불법강호" placeholder="새 프로젝트명 또는 기존 프로젝트명"><input id="idea" value="현대 서울에 깨어난 백 년 전 무인이 국가등록무림과 충돌하는 3분 시리즈" placeholder="한 줄 아이디어"></div><textarea id="masterPrompt" class="masterPrompt">현재 원고로 1분짜리 쇼츠 프리뷰를 만들어줘. 한국어 내레이션과 자막을 넣고, 바로 재생 가능한 mp4까지 만들어줘.</textarea><div class="tabs"><button id="tab_project" class="tab active" onclick="tab('project')"><b>1 프로젝트</b><span>새로 만들기/기존 선택</span></button><button id="tab_scenario" class="tab" onclick="tab('scenario')"><b>2 시나리오</b><span>원고 작성/수정</span></button><button id="tab_prompt" class="tab" onclick="tab('prompt')"><b>3 프롬프트</b><span>장면·이미지 지시</span></button><button id="tab_media" class="tab" onclick="tab('media')"><b>4 이미지·음성</b><span>TTS/음악/자산</span></button><button id="tab_video" class="tab" onclick="tab('video')"><b>5 동영상</b><span>렌더/프리뷰</span></button><button id="tab_edit" class="tab" onclick="tab('edit')"><b>6 편집/Export</b><span>검수/내보내기</span></button></div></div></div><div class="card"><div class="head">프리뷰</div><div class="body"><video id="video" controls></video><div id="previewText" class="small">전체 자동 제작 후 여기에 표시됩니다.</div></div></div></section><section class="workspace" style="margin-top:16px"><div class="card"><div class="head">프로젝트 목록<button onclick="loadProjects()">갱신</button></div><div class="body"><div id="projects"></div></div></div><div class="card"><div class="head"><span id="stageTitle">프로젝트</span><button class="ghost" onclick="saveDraft()">저장</button></div><div class="body"><div id="panel_project" class="stagePanel active"><h2>새 프로젝트 또는 기존 프로젝트</h2><p class="small">새 이름을 입력하고 전체 자동 제작을 누르면 새 프로젝트가 만들어집니다. 기존 프로젝트를 누르면 이어서 수정/제작합니다.</p><div class="actions"><button class="primary" onclick="planOnly()">새 프로젝트/기획 생성</button><button onclick="refresh()">현재 프로젝트 불러오기</button></div></div><div id="panel_scenario" class="stagePanel"><textarea id="scenario" class="script"></textarea><div class="actions"><button class="primary" onclick="saveDraft()">원고 저장</button><button onclick="planOnly()">이 원고로 장면 재구성</button></div></div><div id="panel_prompt" class="stagePanel"><textarea id="stagePrompt" class="promptBox" placeholder="예: 장면을 더 영화적으로, 검은 기운은 절제된 공포로 표현"></textarea><div class="actions"><button onclick="planOnly()">프롬프트 반영해 제작계획 갱신</button><button onclick="showPromptData()">생성된 프롬프트 보기</button></div><div id="sceneList"></div></div><div id="panel_media" class="stagePanel"><textarea class="promptBox" placeholder="예: 차분한 남성 내레이션, 낮은 북소리, 절제된 긴장감"></textarea><div class="actions"><button class="primary" onclick="ttsOnly()">TTS 생성</button><button onclick="inspectOnly()">자산 검수</button></div></div><div id="panel_video" class="stagePanel"><textarea class="promptBox" placeholder="예: 자막을 영상에 입히고, 바로 재생 가능한 mp4로 만들어줘"></textarea><div class="actions"><button class="primary" onclick="previewOnly()">동영상 렌더</button><button onclick="makeAll()">전체 다시 제작</button></div></div><div id="panel_edit" class="stagePanel"><textarea class="promptBox" placeholder="예: 누락된 자산을 확인하고 다음 작업을 알려줘"></textarea><div class="actions"><button class="primary" onclick="inspectOnly()">검수 리포트</button><button onclick="showDetail()">상세 보기</button></div></div></div></div><div class="card"><div class="head">진행 상태</div><div class="body"><div id="steps" class="steps"></div></div></div></section><section class="workspace" style="grid-template-columns:1fr 1fr;margin-top:16px"><div class="card"><div class="head">작업 로그</div><div class="body"><div id="log" class="log"></div></div></div><div class="card"><div class="head">상세/리포트</div><div class="body"><pre id="detail" class="log"></pre></div></div></section></div><div id="settings" class="settings"><h3>설정</h3><p class="small">초보자는 기본값 그대로 사용하면 됩니다.</p><label>TTS 음성</label><select id="voice"><option>Microsoft Heami Desktop</option><option>Microsoft Zira Desktop</option><option>Microsoft David Desktop</option></select><label>자막</label><select id="burn"><option value="true">영상에 직접 넣기</option><option value="false">자막 파일만 만들기</option></select><label>작업 모드</label><select><option>자동: 기본 권장값</option><option>전문가: 단계별 수동 확인</option></select><button onclick="toggleSettings()">닫기</button></div><div class="bar"><input id="quick" placeholder="자연어 명령: 예) 기존 프로젝트 이어서 프리뷰 다시 만들어줘"><button class="good" onclick="quickRun()">실행</button></div><script>
const DEFAULT_SCENARIO=`__SCENARIO__`;scenario.value=DEFAULT_SCENARIO;let current='project';let lastProject=null;function logMsg(s){log.textContent+=(log.textContent?'\n':'')+'['+new Date().toLocaleTimeString()+'] '+s;log.scrollTop=log.scrollHeight}function toggleSettings(){settings.classList.toggle('show')}function tab(n){current=n;['project','scenario','prompt','media','video','edit'].forEach(x=>{document.getElementById('tab_'+x).classList.toggle('active',x===n);document.getElementById('panel_'+x).classList.toggle('active',x===n)});stageTitle.textContent={project:'프로젝트',scenario:'시나리오',prompt:'프롬프트',media:'이미지·음성',video:'동영상',edit:'편집/Export'}[n]}async function api(p,d){const r=await fetch(p,{method:'POST',headers:{'Content-Type':'application/json; charset=utf-8'},body:JSON.stringify(d||{})});const j=await r.json();if(!j.ok)throw new Error(j.error||'실패');return j}async function getJson(p){const r=await fetch(p);return await r.json()}function data(){return{title:title.value.trim()||'불법강호',idea:idea.value.trim(),scenario:scenario.value,command:(quick.value||masterPrompt.value),voice:voice.value,burn_subtitles:burn.value==='true'}}async function loadProjects(){const j=await getJson('/api/projects');projects.innerHTML='';(j.projects||[]).forEach(p=>{const d=document.createElement('div');d.className='project'+(p.title===title.value?' active':'');d.innerHTML='<b>'+esc(p.title)+'</b><div class="small">'+esc(p.status||'대기')+'</div>';d.onclick=()=>selectProject(p.title);projects.appendChild(d)})}async function selectProject(t){title.value=t;lastProject=t;await refresh();await loadProjects()}async function refresh(){const j=await getJson('/api/project?title='+encodeURIComponent(title.value.trim()||'불법강호'));if(j.scenario)scenario.value=j.scenario;if(j.idea)idea.value=j.idea;projectState.textContent=title.value.trim()||'프로젝트';renderStatus(j);renderPreview(j);renderScenes(j);detail.textContent=JSON.stringify({asset:j.asset_manifest&&j.asset_manifest.summary,preview:j.preview_result},null,2)}function renderPreview(j){if(j.preview_url){video.src=j.preview_url+'?t='+Date.now();previewText.textContent='프리뷰 준비 완료'}else{previewText.textContent='아직 프리뷰가 없습니다.'}}function renderStatus(j){const s=(j.asset_manifest&&j.asset_manifest.summary)||{};const audio=(j.preview_result&&j.preview_result.audio)||{};assetState.textContent=s.total?'자산 '+s.existing+'/'+s.total+' · 누락 '+s.missing:'자산 대기';const rows=[['프로젝트',!!j.project],['시나리오/장면',!!j.keyframe_prompts],['이미지 프롬프트',!!j.keyframe_prompts],['TTS 음성',audio.used_real_audio_count>0],['동영상',!!j.preview_url],['검수',s.total&&s.missing===0]];steps.innerHTML='';rows.forEach(r=>{const d=document.createElement('div');d.className='step';d.innerHTML='<span>'+r[0]+'</span><span class="dot '+(r[1]?'ok':'')+'"></span>';steps.appendChild(d)})}function renderScenes(j){sceneList.innerHTML='';const arr=(j.keyframe_prompts&&j.keyframe_prompts.prompts)||[];arr.slice(0,8).forEach((p,i)=>{const d=document.createElement('div');d.className='sceneCard';d.innerHTML='<b>'+(i+1)+'. '+esc(p.scene_title||'장면')+'</b><div class="small">'+esc(p.keyframe_id||'keyframe')+'</div><div class="small">'+esc((p.prompt||'').slice(0,180))+'</div>';sceneList.appendChild(d)})}async function makeAll(){try{logMsg('전체 자동 제작 시작');const j=await api('/api/command',{...data(),command:'전체 제작'});logMsg(j.message);await refresh();await loadProjects();tab('video')}catch(e){logMsg(e.message)}}async function planOnly(){try{logMsg('기획 생성');const j=await api('/api/pipeline/run',data());logMsg('기획 완료');await refresh();await loadProjects();tab('prompt')}catch(e){logMsg(e.message)}}async function ttsOnly(){try{logMsg('TTS 생성');const j=await api('/api/tts/synth',data());logMsg('TTS 완료 '+(j.ok_count||0)+'/'+(j.total||0));await refresh()}catch(e){logMsg(e.message)}}async function previewOnly(){try{logMsg('동영상 렌더');const j=await api('/api/preview/render',data());logMsg(j.mode||'렌더 완료');await refresh();tab('video')}catch(e){logMsg(e.message)}}async function inspectOnly(){try{const j=await api('/api/assets/inspect',data());logMsg('검수 완료 · 누락 '+j.missing);detail.textContent=j.report||'';await refresh();tab('edit')}catch(e){logMsg(e.message)}}async function saveDraft(){try{const j=await api('/api/scenario/save',data());logMsg('저장 완료');await refresh()}catch(e){logMsg(e.message)}}async function quickRun(){if(!quick.value.trim())return;const j=await api('/api/command',{...data(),command:quick.value});logMsg(j.message);await refresh();await loadProjects()}async function showPromptData(){const j=await getJson('/api/project?title='+encodeURIComponent(title.value.trim()||'불법강호'));detail.textContent=JSON.stringify(j.keyframe_prompts||{},null,2)}function showDetail(){refresh()}function esc(s){return String(s||'').replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]))}loadProjects().then(refresh).catch(e=>logMsg(e.message));
</script></body></html>'''.replace('__SCENARIO__', DEFAULT_SCENARIO.replace('`','\\`'))

class Handler(BaseHTTPRequestHandler):
    workspace: Path = ROOT_DIR
    def send_json(self,payload:Any,status:int=200)->None:
        data=json.dumps(payload,ensure_ascii=False).encode('utf-8');self.send_response(status);self.send_header('Content-Type','application/json; charset=utf-8');self.send_header('Content-Length',str(len(data)));self.end_headers();self.wfile.write(data)
    def send_html(self)->None:
        data=HTML.encode('utf-8');self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8');self.send_header('Content-Length',str(len(data)));self.end_headers();self.wfile.write(data)
    def body(self)->Dict[str,Any]:
        n=int(self.headers.get('Content-Length','0') or '0');return json.loads(self.rfile.read(n).decode('utf-8')) if n else {}
    def do_GET(self)->None:
        p=urlparse(self.path)
        try:
            if p.path=='/': self.send_html()
            elif p.path=='/api/projects': self.send_json({'ok':True,'projects':list_projects(self.workspace)})
            elif p.path=='/api/project': self.send_json(load_project_payload(self.workspace,parse_qs(p.query).get('title',['불법강호'])[0]))
            elif p.path.startswith('/media/'): self.media(p.path)
            else: self.send_json({'ok':False,'error':'not found'},404)
        except Exception as e: self.send_json({'ok':False,'error':str(e)},500)
    def do_POST(self)->None:
        try:
            b=self.body();p=urlparse(self.path).path;title=str(b.get('title','불법강호')).strip() or '불법강호';idea=str(b.get('idea',DEFAULT_IDEA)).strip() or DEFAULT_IDEA;scenario=str(b.get('scenario',DEFAULT_SCENARIO)) or DEFAULT_SCENARIO
            if p=='/api/scenario/save': self.send_json({'ok':True,**save_scenario(self.workspace,title,idea,scenario)})
            elif p=='/api/pipeline/run': save_scenario(self.workspace,title,idea,scenario);self.send_json({'ok':True,**run_pipeline(self.workspace,title,idea,scenario)})
            elif p=='/api/tts/synth': self.send_json({'ok':True,**synth_tts(self.workspace,title,str(b.get('voice','Microsoft Heami Desktop')))})
            elif p=='/api/preview/render': self.send_json({'ok':True,**render_preview(self.workspace,title,bool(b.get('burn_subtitles',True)))})
            elif p=='/api/assets/inspect': self.send_json({'ok':True,**inspect_assets(self.workspace,title)})
            elif p=='/api/command': self.send_json({'ok':True,**self.command(b,title,idea,scenario)})
            else: self.send_json({'ok':False,'error':'not found'},404)
        except Exception as e: self.send_json({'ok':False,'error':str(e)},500)
    def command(self,b:Dict[str,Any],title:str,idea:str,scenario:str)->Dict[str,Any]:
        cmd=str(b.get('command','')).lower();save_scenario(self.workspace,title,idea,scenario)
        if any(k in cmd for k in ['전체','제작','만들','프리뷰','영상','쇼츠']): run_pipeline(self.workspace,title,idea,scenario);synth_tts(self.workspace,title,str(b.get('voice','Microsoft Heami Desktop')));render_preview(self.workspace,title,bool(b.get('burn_subtitles',True)));inspect_assets(self.workspace,title);return {'message':'전체 자동 제작 완료'}
        if any(k in cmd for k in ['계획','분석','장면','프롬프트']): run_pipeline(self.workspace,title,idea,scenario);return {'message':'제작계획 생성 완료'}
        if any(k in cmd for k in ['음성','tts','내레이션']): synth_tts(self.workspace,title,str(b.get('voice','Microsoft Heami Desktop')));return {'message':'TTS 생성 완료'}
        if any(k in cmd for k in ['검수','자산','리포트']): inspect_assets(self.workspace,title);return {'message':'자산 검수 완료'}
        return {'message':'원고 저장 완료'}
    def media(self,path_text:str)->None:
        rel=path_text[len('/media/'):];path=(self.workspace/'local_projects'/rel).resolve();root=(self.workspace/'local_projects').resolve()
        if not str(path).startswith(str(root)) or not path.exists(): self.send_response(404);self.end_headers();return
        data=path.read_bytes();self.send_response(200);self.send_header('Content-Type','video/mp4');self.send_header('Content-Length',str(len(data)));self.end_headers();self.wfile.write(data)
    def log_message(self,format:str,*args:Any)->None: return

def main()->int:
    parser=argparse.ArgumentParser(description='Run modern staged prompt magicStudio UI');parser.add_argument('--workspace',default='.');parser.add_argument('--host',default='127.0.0.1');parser.add_argument('--port',type=int,default=7864);args=parser.parse_args();Handler.workspace=Path(args.workspace).resolve();server=ThreadingHTTPServer((args.host,args.port),Handler);print('=== magicStudio Modern UI ===');print(f'workspace: {Handler.workspace}');print(f'url: http://{args.host}:{args.port}')
    try: server.serve_forever()
    except KeyboardInterrupt: print('\nshutdown')
    finally: server.server_close()
    return 0
if __name__=='__main__': raise SystemExit(main())
